+function parseTags(value: unknown): string[] {
+  if (Array.isArray(value)) return value.map(String).map(tag => tag.trim()).filter(Boolean);
+  if (typeof value === 'string') return value.split(',').map(tag => tag.trim()).filter(Boolean);
+  return [];
