+    await runHook(plugins, 'afterBuild', context);
+    return context.pages;
+  } catch (error) {
+    buildError = error;
+    throw error;
+  } finally {
+    try {
+      await runHook(plugins, 'onEnd', context);
+    } catch (error) {
+      if (buildError === undefined) throw error;
+    }
+  }
