function listen(server: Server, port: number, host: string): Promise<void> {
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, host, () => {
      server.off('error', reject);
      resolve();
    });
  });
}

export class DevServerPlugin implements Plugin {
  readonly name = 'dev-server';

  constructor(private readonly reload: () => void = () => undefined) {}

  afterBuild(_context: BuildContext): void {
    this.reload();
  }
}

export async function startDevServer(options: DevServerOptions = {}): Promise<DevServer> {
  const outputDir = path.resolve(options.outputDir ?? 'dist');
  const contentDir = path.resolve(options.contentDir ?? 'content');
  const templatesDir = path.resolve(options.templatesDir ?? 'templates');
  const port = options.port ?? 3000;
  const host = options.host ?? 'localhost';

  let sockets: WebSocketServer | undefined;
  const devServer = new DevServerPlugin(() => {
    if (!sockets) return;
    for (const client of sockets.clients) {
      if (client.readyState === WebSocket.OPEN) client.send('reload');
    }
  });
  const buildOptions: BuildOptions = {
    contentDir,
    outputDir,
    templatesDir,
    configFile: options.configFile,
    plugins: options.plugins ? [...options.plugins, devServer] : undefined
  };
  await buildSite(buildOptions.plugins
    ? buildOptions
    : { ...buildOptions, plugins: [...loadServerPlugins(buildOptions), devServer] });

  const server = createServer(async (request, response) => {
    try {
      const pathname = decodeURIComponent(new URL(request.url ?? '/', 'http://localhost').pathname);
      const relative = pathname === '/' ? 'index.html' : pathname.replace(/^\/+/, '');
      let filename = path.resolve(outputDir, relative);
      if (filename !== outputDir && !filename.startsWith(`${outputDir}${path.sep}`)) {
        response.writeHead(403).end('Forbidden');
        return;
      }

      let stat = await fs.stat(filename);
      if (stat.isDirectory()) {
        filename = path.join(filename, 'index.html');
        stat = await fs.stat(filename);
      }

      const extension = path.extname(filename).toLowerCase();
      response.setHeader('Content-Type', contentTypes[extension] ?? 'application/octet-stream');
      response.setHeader('Cache-Control', 'no-store');
      if (extension === '.html') {
        response.end(injectReload(await fs.readFile(filename, 'utf8')));
      } else {
        response.setHeader('Content-Length', stat.size);
        createReadStream(filename).pipe(response);
      }
    } catch (error) {
      const status = (error as NodeJS.ErrnoException).code === 'ENOENT' ? 404 : 500;
      response.writeHead(status, { 'Content-Type': 'text/plain; charset=utf-8' });
      response.end(status === 404 ? 'Not found' : 'Internal server error');
    }
  });
  sockets = new WebSocketServer({ noServer: true });
  server.on('upgrade', (request, socket, head) => {
    if (request.url !== '/__ssg_reload') {
      socket.destroy();
      return;
    }
    sockets.handleUpgrade(request, socket, head, client => sockets.emit('connection', client, request));
  });

  let rebuilding = false;
  let rebuildAgain = false;
  const rebuild = async (): Promise<void> => {
    if (rebuilding) {
      rebuildAgain = true;
      return;
    }
    rebuilding = true;
    do {
      rebuildAgain = false;
      try {
        await buildSite(buildOptions.plugins
          ? buildOptions
          : { ...buildOptions, plugins: [...loadServerPlugins(buildOptions), devServer] });
      } catch (error) {
        options.io?.stderr.write(`Rebuild failed: ${error instanceof Error ? error.message : String(error)}\n`);
      }
    } while (rebuildAgain);
    rebuilding = false;
  };

  let watcher: FSWatcher | undefined;
  try {
    await listen(server, port, host);
    watcher = chokidar.watch([contentDir, templatesDir], { ignoreInitial: true });
    watcher.on('all', () => void rebuild());
    await new Promise<void>((resolve, reject) => {
      watcher?.once('ready', resolve);
      watcher?.once('error', reject);
    });
  } catch (error) {
    sockets.close();
    server.close();
    throw error;
  }

  const address = server.address();
  const actualPort = typeof address === 'object' && address ? address.port : port;
  return {
    port: actualPort,
    async close(): Promise<void> {
      await watcher?.close();
      for (const client of sockets.clients) client.terminate();
      await new Promise<void>(resolve => sockets.close(() => resolve()));
      await new Promise<void>((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
    }
  };
}

function loadServerPlugins(options: BuildOptions): Plugin[] {
  // Delay this import to keep the public server module independent of config loading internals.
  return require('./config').loadPlugins(options) as Plugin[];
}

